    },
    {
      "id": "LOCATION_DEFAULT",
      "lat": -8.501291299491179,
      "lng": 115.24997038782783,
      "title": "Where you’ll be"
    },
    {
      "id": "HIGHLIGHTS_DEFAULT",
      "highlights": "Designed by, Dive right in, Extra spacious"
